package ug.audiocity.studio;
import java.io.*;import java.nio.*;
/** Deterministic playback utilities for bundled, standardised sample assets. */
public final class SampleAudio {
 static byte[] readBytes(InputStream in,int length)throws IOException{byte[] b=new byte[length];int offset=0;while(offset<length){int n=in.read(b,offset,length-offset);if(n<0)throw new EOFException("Truncated sample");offset+=n;}return b;}
 static int le(byte[] b,int pos){return (b[pos]&255)|((b[pos+1]&255)<<8)|((b[pos+2]&255)<<16)|(b[pos+3]<<24);}
 public static float[] readWav(InputStream input)throws IOException{BufferedInputStream in=new BufferedInputStream(input);byte[] header=readBytes(in,12);if(!new String(header,0,4,"US-ASCII").equals("RIFF")||!new String(header,8,4,"US-ASCII").equals("WAVE"))throw new IOException("Invalid WAV asset");boolean format=false;int channels=0;for(int count=0;count<32;count++){byte[] block=readBytes(in,8);String id=new String(block,0,4,"US-ASCII");int size=le(block,4);if(size<0||size>67108864)throw new IOException("Invalid WAV chunk size");if(id.equals("fmt ")){if(size<16||size>4096)throw new IOException("Invalid WAV format chunk");byte[] f=readBytes(in,size);ByteBuffer b=ByteBuffer.wrap(f).order(ByteOrder.LITTLE_ENDIAN);int encoding=b.getShort(0),bits=b.getShort(14),rate=b.getInt(4);channels=b.getShort(2);if(encoding!=1||bits!=16||rate!=Core.RATE||(channels!=1&&channels!=2))throw new IOException("Sample assets must be 48 kHz / 16-bit PCM");format=true;}else if(id.equals("data")){if(!format||size==0||size%(channels*2)!=0)throw new IOException("Invalid WAV data");byte[] pcm=readBytes(in,size);int frames=size/(channels*2);float[] output=new float[frames*2];ByteBuffer b=ByteBuffer.wrap(pcm).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<frames;i++){float left=b.getShort()/32768f,right=channels==1?left:b.getShort()/32768f;output[i*2]=left;output[i*2+1]=right;}return output;}else{int remaining=size;while(remaining>0){long skipped=in.skip(remaining);if(skipped==0){if(in.read()<0)throw new EOFException();skipped=1;}remaining-=skipped;}}if((size&1)==1&&in.read()<0)throw new EOFException();}throw new IOException("No sample data chunk");}
 public static float[] fitLoop(float[] data,int bars,int bpm){if(data.length==0||data.length%2!=0||bars<1||bars>16||bpm<40||bpm>240)throw new IllegalArgumentException("Invalid tempo-fit input");int sourceFrames=data.length/2,targetFrames=(int)Math.round(Core.RATE*60.0/bpm*4*bars);float[] out=new float[targetFrames*2];for(int i=0;i<targetFrames;i++){double at=i*(sourceFrames/(double)targetFrames);int a=Math.min(sourceFrames-1,(int)at),b=Math.min(sourceFrames-1,a+1);float t=(float)(at-a);out[2*i]=data[2*a]+(data[2*b]-data[2*a])*t;out[2*i+1]=data[2*a+1]+(data[2*b+1]-data[2*a+1])*t;}return out;}
 public static float[] pattern(int bpm,boolean[][] steps,float[][] voices,float[] levels,int bars){if(bpm<40||bpm>240||bars<1||bars>8||steps.length!=voices.length||levels.length!=voices.length)throw new IllegalArgumentException("Invalid sample sequence");int frames=(int)Math.round(Core.RATE*60.0/bpm*4*bars);float[] out=new float[frames*2];for(int lane=0;lane<steps.length;lane++){if(steps[lane].length!=16||voices[lane].length%2!=0)throw new IllegalArgumentException("Expected 16 stereo steps");for(int bar=0;bar<bars;bar++)for(int step=0;step<16;step++)if(steps[lane][step]){int start=(int)Math.round((bar*16+step)*(Core.RATE*60.0/bpm/4))*2;for(int i=0;i<voices[lane].length&&start+i<out.length;i++)out[start+i]+=voices[lane][i]*levels[lane];}}return out;}
}
